 m jsonb := $manifest${"batch":"sail-result-2026-2026-10-22","officialSource":{"id":182439,"url":"https://www.racingrulesofsailing.org/documents/182439","title":"Official 2026-trat-regatta result document 182439","type":"pdf","visuallyReviewed":true,"provisional":false,"page":1,"pages":[1],"comparison":"All source race scores, discard markers and codes extracted from reviewed official tables; row arithmetic reconciled.","secondaryUrl":"https://sail-result.com/result_detail.html?event=2026%20Trat%20Regatta"},"event":{"id":"5da83b8f-2063-5f39-bb69-f19cfcda1e04","slug":"trat-regatta-2026","name":"2026 Trat Regatta","startDate":"2026-04-04","endDate":"2026-04-06","venue":"Oceanfront Pier, Laem Sok, Trat","organizer":"Yacht Racing Association of Thailand","classes":["ILCA 4","ILCA 6","ILCA 7","Optimist"],"existing":false},"sheet":{"id":"d90f3cad-8909-5e20-8939-251d09c0a31a","slug":"trat-regatta-2026-ilca6","name":"2026 Trat Regatta — ILCA 6","boatClass":"ILCA 6","division":"Open","raceCount":8,"totalFleetSize":3,"countsForRanking":false,"status":"published","entryType":"individual","minParticipants":1,"maxParticipants":1},"results":[{"eventKey":"2026-trat-regatta","boatClass":"ILCA 6","division":"Open","source":{"id":182439,"url":"https://www.racingrulesofsailing.org/documents/182439","title":"Official 2026-trat-regatta result document 182439","type":"pdf","visuallyReviewed":true,"provisional":false,"page":1},"rank":1,"name":"PATCHAREE SRINGAM","sailOrBoardNumber":"225984","club":"YRAT","school":null,"nationality":"THA","gender":"F","officialBirthYear":2003,"sourceBirthYear":"2003","grossScore":9.0,"nettScore":7.0,"races":[{"raceNumber":1,"score":1.0,"code":null,"discarded":false,"raw":"1.0","sourceRaceLabel":"R1"},{"raceNumber":2,"score":1.0,"code":null,"discarded":false,"raw":"1.0","sourceRaceLabel":"R2"},{"raceNumber":3,"score":1.0,"code":null,"discarded":false,"raw":"1.0","sourceRaceLabel":"R3"},{"raceNumber":4,"score":1.0,"code":null,"discarded":false,"raw":"1.0","s